-- Z-07 租户、计量计费与可信平台交换
create table if not exists ds_tenant (id varchar(64) primary key, name varchar(128) not null, owner_id varchar(128) not null, status varchar(32) not null default 'PENDING', deploy_endpoint varchar(512) default '', cpu_cores real not null default 4, memory_gb real not null default 16, gpu_count integer not null default 0, storage_gb real not null default 100, signing_secret varchar(256) not null, created_by varchar(128) default '', created_at varchar(32) not null, updated_at varchar(32) not null);
create unique index if not exists uk_ds_tenant_owner_name on ds_tenant(owner_id, name);
create table if not exists ds_usage_meter (id varchar(64) primary key, tenant_id varchar(64) not null, resource_type varchar(32) not null, amount real not null default 0, unit varchar(16) not null, period_start varchar(32) not null, period_end varchar(32) not null, source varchar(64) default 'sandbox', created_at varchar(32) not null);
create table if not exists ds_billing_record (id varchar(64) primary key, tenant_id varchar(64) not null, period_start varchar(32) not null, period_end varchar(32) not null, amount real not null default 0, currency varchar(8) not null default 'CNY', status varchar(32) not null default 'CALCULATED', reported_at varchar(32) default '', created_at varchar(32) not null);
create table if not exists ds_trusted_exchange (id varchar(64) primary key, tenant_id varchar(64) not null, direction varchar(16) not null, event_type varchar(64) not null, idempotency_key varchar(128) not null, payload varchar(8192) not null, payload_hash varchar(128) not null, signature varchar(128) not null, status varchar(32) not null default 'PENDING', attempts integer not null default 0, last_error varchar(1024) default '', created_at varchar(32) not null, updated_at varchar(32) not null);
create unique index if not exists uk_ds_exchange_idempotency on ds_trusted_exchange(tenant_id, idempotency_key);
create table if not exists ds_access_policy (id varchar(64) primary key, tenant_id varchar(64) not null, subject varchar(128) not null, action varchar(64) not null, resource varchar(256) not null, effect varchar(16) not null default 'ALLOW', expires_at varchar(32) default '', created_by varchar(128) default '', created_at varchar(32) not null);
